for li, lang in enumerate(["es","en","it"]):
    ui = UI[lang]
    ui["metrics"] = {k: v[li*2] for k, v in M.items()}
    ui["metricDesc"] = {k: v[li*2+1] for k, v in M.items()}
    ui["groups"] = {k: v[li] for k, v in G.items()}
    p = f"src/locales/{lang}/translation.json"
    raw = open(p).read()
    d = json.loads(raw, object_pairs_hook=collections.OrderedDict)
    d["playerStats"] = ui
    open(p, "w").write(json.dumps(d, ensure_ascii=False, indent=2) + "\n")
